143→// ─── Loader ───────────────────────────────────────────────────────────────────
144→
145→export const loader = async ({ request }: LoaderFunctionArgs) => {
146→  const { session } = await authenticate.admin(request);
147→  const shop = session.shop;
148→  const subscription = await getShopSubscription(shop);
149→  return { subscription };
150→};
151→
152→// ─── Action ───────────────────────────────────────────────────────────────────
153→
154→export const action = async ({ request }: ActionFunctionArgs): Promise<
155→  | { error: string }
156→  | { success: boolean; message: string }
157→  | null
158→> => {
159→  const { session, billing } = await authenticate.admin(request);
160→  const shop = session.shop;
161→  const formData = await request.formData();
162→  const intent = String(formData.get("intent"));
163→
164→  if (intent === "subscribe") {
165→    const plan = String(formData.get("plan"));
166→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
167→    try {
168→      /* eslint-disable @typescript-eslint/no-explicit-any */
169→      // billing.request() throws a redirect Response to Shopify's
170→      // billing confirmation page — we must let it propagate.
171→      await billing.request({
172→        plan: plan as any,
173→        isTest: process.env.NODE_ENV !== "production",
174→        returnUrl,
175→      });
176→      /* eslint-enable @typescript-eslint/no-explicit-any */
177→      return null;
178→    } catch (error) {
179→      // Re-throw Response redirects so React Router / App Bridge handles them
180→      if (error instanceof Response) throw error;
181→      // BillingError has errorData with Shopify userErrors
182→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
183→      const details = errorData?.map((e) => e.message).join(", ");
184→      const message = details || (error instanceof Error ? error.message : String(error));
185→
186→      // Provide a helpful message for common billing errors
187→      if (message.includes("Custom apps cannot use the Billing API")) {
188→        return {
189→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
190→        };
191→      }
192→      return {
193→        error: `Failed to initiate subscription: ${message}`,
194→      };
195→    }
196→  }
197→
198→  // Set plan directly in database (for custom apps where Billing API is unavailable)
199→  if (intent === "test-set-plan") {
200→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
201→    const validTiers = ["free", "starter", "pro", "ultimate"];
202→    if (!validTiers.includes(tier)) {
203→      return { error: `Invalid plan tier: ${tier}` };
204→    }
205→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
206→    await db.subscription.upsert({
207→      where: { shop },
208→      create: { shop, planId, billingInterval: "monthly", status: "active" },
209→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
210→    });
211→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
212→  }
213→
214→  if (intent === "cancel") {
215→    try {
216→      const sub = await getShopSubscription(shop);
217→      if (sub.shopifySubscriptionId) {
218→        await billing.cancel({
219→          subscriptionId: sub.shopifySubscriptionId,
220→          isTest: process.env.NODE_ENV !== "production",
221→          prorate: true,
222→        });
223→      }
224→      await cancelShopSubscription(shop);
225→      return {
226→        success: true,
227→        message: "Subscription cancelled. You are now on the Free plan.",
228→      };
229→    } catch {
230→      return { error: "Failed to cancel subscription. Please try again." };
231→    }
232→  }
233→
234→  return null;
235→};
