237→// ─── Feature row ─────────────────────────────────────────────────────────────
238→
239→function PlanFeature({ feature }: { feature: string }) {
240→  return (
241→    <InlineStack gap="200" blockAlign="start" wrap={false}>
242→      <Box>
243→        <Icon source={CheckCircleIcon} tone="success" />
244→      </Box>
245→      <Text as="span" variant="bodyMd">
246→        {feature}
247→      </Text>
248→    </InlineStack>
249→  );
250→}
