252→// ─── Plan card ────────────────────────────────────────────────────────────────
253→
254→type PlanCardProps = {
255→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
256→  isAnnual: boolean;
257→  currentTier: string;
258→  onSubscribe: (planName: string) => void;
259→  onRequestCancel: () => void;
260→  loadingPlan: string | null;
261→};
262→
263→function PlanCard({
264→  plan,
265→  isAnnual,
266→  currentTier,
267→  onSubscribe,
268→  onRequestCancel,
269→  loadingPlan,
270→}: PlanCardProps) {
271→  const isCurrent = currentTier === plan.id;
272→  const isBestValue = "bestValue" in plan && plan.bestValue;
273→  const isCurrentPaid = currentTier !== "free";
274→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
275→
276→  const TIER_ORDER: Record<string, number> = {
277→    free: 0,
278→    starter: 1,
279→    pro: 2,
280→    ultimate: 3,
281→  };
282→  const isUpgrade =
283→    !isCurrent &&
284→    plan.id !== "free" &&
285→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
286→
287→  const shopifyPlan = isAnnual
288→    ? plan.shopifyPlanAnnual
289→    : plan.shopifyPlanMonthly;
290→
291→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
292→
293→  let buttonContent = "Start 7-day free trial";
294→  if (isCurrent) {
295→    buttonContent = "Current plan";
296→  } else if (isDowngradeToFree) {
297→    buttonContent = "Downgrade to Free";
298→  } else if (isUpgrade) {
299→    buttonContent = `Upgrade to ${plan.name}`;
300→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
301→    buttonContent = `Switch to ${plan.name}`;
302→  }
303→
304→  const handleClick = () => {
305→    if (isCurrent) return;
306→    if (isDowngradeToFree) {
307→      onRequestCancel();
308→    } else if (shopifyPlan) {
309→      onSubscribe(shopifyPlan);
310→    }
311→  };
312→
313→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
314→
315→  return (
316→    <Box
317→      background="bg-surface"
318→      borderWidth="025"
319→      borderColor={isBestValue ? "border-info" : "border"}
320→      borderRadius="300"
321→      padding="0"
322→      overflowX="hidden"
323→      overflowY="hidden"
324→    >
325→      {/* Best value ribbon */}
326→      {isBestValue && (
327→        <Box background="bg-fill-info" padding="200">
328→          <Text as="p" variant="bodySm" fontWeight="semibold" alignment="center" tone="text-inverse">
329→            Most Popular
330→          </Text>
331→        </Box>
332→      )}
333→
334→      <Box padding="400">
335→        <BlockStack gap="400">
336→          {/* Plan name + badge */}
337→          <InlineStack align="space-between" blockAlign="center">
338→            <Text as="h3" variant="headingMd" fontWeight="bold">
339→              {plan.name}
340→            </Text>
341→            {isCurrent && <Badge tone="success">Active</Badge>}
342→          </InlineStack>
343→
344→          {/* Price */}
345→          <BlockStack gap="050">
346→            <InlineStack gap="100" blockAlign="baseline">
347→              <Text as="p" variant="headingXl" fontWeight="bold">
348→                ${displayPrice}
349→              </Text>
350→              <Text as="p" variant="bodySm" tone="subdued">
351→                / month
352→              </Text>
353→            </InlineStack>
354→            <Text as="p" variant="bodySm" tone="subdued">
355→              {isAnnual
356→                ? `billed $${plan.annualPrice} / year`
357→                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
358→            </Text>
359→          </BlockStack>
360→
361→          {/* CTA Button */}
362→          <Button
363→            variant={isCurrent ? "secondary" : "primary"}
364→            tone={isDowngradeToFree ? "critical" : undefined}
365→            onClick={handleClick}
366→            disabled={isCurrent}
367→            loading={isThisLoading}
368→            fullWidth
369→          >
370→            {buttonContent}
371→          </Button>
372→
373→          <Divider />
374→
375→          {/* Features list */}
376→          <BlockStack gap="200">
377→            <Text as="p" variant="bodySm" fontWeight="semibold" tone="subdued">
378→              {plan.id === "ultimate" ? "Everything in Pro, plus:" : "Includes:"}
379→            </Text>
380→            {plan.features.map((f) => (
381→              <PlanFeature key={f} feature={f} />
382→            ))}
383→          </BlockStack>
384→        </BlockStack>
385→      </Box>
386→    </Box>
387→  );
388→}
