390→// ─── Page ─────────────────────────────────────────────────────────────────────
391→
392→export default function PricingPage() {
393→  const { subscription } = useLoaderData<typeof loader>();
394→  const fetcher = useFetcher<typeof action>();
395→  const navigate = useNavigate();
396→  const shopify = useAppBridge();
397→
398→  const [isAnnual, setIsAnnual] = useState(
399→    subscription.billingInterval === "annual",
400→  );
401→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
402→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
403→
404→  const data = fetcher.data;
405→  const isFetching = fetcher.state !== "idle";
406→
407→  // Toast for success, Banner for errors (errors must not auto-dismiss)
408→  useEffect(() => {
409→    if (!isFetching) setLoadingPlan(null);
410→    if (data && "message" in data && data.message) {
411→      shopify.toast.show(data.message as string);
412→    }
413→  }, [data, isFetching, shopify]);
414→
415→  const actionError =
416→    data && "error" in data && data.error ? (data.error as string) : null;
417→
418→  const handleSubscribe = useCallback(
419→    (planName: string) => {
420→      setLoadingPlan(planName);
421→      const fd = new FormData();
422→      fd.set("intent", "subscribe");
423→      fd.set("plan", planName);
424→      fetcher.submit(fd, { method: "POST" });
425→    },
426→    [fetcher],
427→  );
428→
429→  const handleConfirmCancel = useCallback(() => {
430→    setCancelModalOpen(false);
431→    setLoadingPlan("cancel");
432→    const fd = new FormData();
433→    fd.set("intent", "cancel");
434→    fetcher.submit(fd, { method: "POST" });
435→  }, [fetcher]);
436→
437→  const currentTier = subscription.planTier;
438→  const currentPlanName =
439→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
440→
441→  // Suggest next tier for upgrade banner
442→  const nextTier =
443→    currentTier === "free"
444→      ? "starter"
445→      : currentTier === "starter"
446→        ? "pro"
447→        : null;
448→
449→  return (
450→    <Page
451→      title="Pricing"
452→      subtitle="Choose the plan that's right for your store"
453→      backAction={{ onAction: () => navigate("/app") }}
454→    >
455→      <Box paddingBlockEnd="1600">
456→      <Layout>
457→        {actionError && (
458→          <Layout.Section>
459→            <Banner tone="critical" title="Billing error">
460→              <Text as="p" variant="bodyMd">{actionError}</Text>
461→            </Banner>
462→          </Layout.Section>
463→        )}
464→        <Layout.Section>
465→          <BlockStack gap="600">
466→
467→            {/* Current plan status */}
468→            {nextTier ? (
469→              <Banner
470→                tone="info"
471→                title={`You're on the ${currentPlanName} plan`}
472→                action={{
473→                  content: `Upgrade to ${PLANS_DATA[nextTier].name}`,
474→                  onAction: () => {
475→                    const plan = isAnnual
476→                      ? PLANS_DATA[nextTier].shopifyPlanAnnual
477→                      : PLANS_DATA[nextTier].shopifyPlanMonthly;
478→                    if (plan) handleSubscribe(plan);
479→                  },
480→                }}
481→              >
482→                <Text as="p" variant="bodyMd">
483→                  {currentTier === "free"
484→                    ? "You have up to 20 allowed zip codes and basic widget access. Upgrade to unlock more features."
485→                    : "Upgrade to Pro for unlimited zip codes, blocked areas, full waitlist, and more."}
486→                </Text>
487→              </Banner>
488→            ) : (
489→              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
490→                <InlineStack gap="200" blockAlign="center">
491→                  <Badge tone="success">Active</Badge>
492→                  <Text as="p" variant="bodyMd">
493→                    {currentTier === "ultimate"
494→                      ? "You have full access to all features including VIP support and API access."
495→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
496→                  </Text>
497→                </InlineStack>
498→              </Banner>
499→            )}
500→
501→            {/* Action feedback banners */}
502→            {data && "success" in data && data.success && (
503→              <Banner tone="success">
504→                {data && "message" in data
505→                  ? String(data.message)
506→                  : "Plan updated successfully."}
507→              </Banner>
508→            )}
509→
510→            {/* Billing toggle */}
511→            <BlockStack gap="200" inlineAlign="center">
512→              <ButtonGroup variant="segmented">
513→                <Button
514→                  pressed={!isAnnual}
515→                  onClick={() => setIsAnnual(false)}
516→                >
517→                  Monthly
518→                </Button>
519→                <Button
520→                  pressed={isAnnual}
521→                  onClick={() => setIsAnnual(true)}
522→                >
523→                  Annual · Save up to 38%
524→                </Button>
525→              </ButtonGroup>
526→              {isAnnual && (
527→                <Badge tone="success">You save up to 38% per year</Badge>
528→              )}
529→            </BlockStack>
530→
531→            {/* Free plan — compact card */}
532→            <Box
533→              background="bg-surface"
534→              borderWidth="025"
535→              borderColor="border"
536→              borderRadius="300"
537→              padding="400"
538→            >
539→              <InlineStack align="space-between" blockAlign="center" wrap>
540→                <InlineStack gap="300" blockAlign="center">
541→                  <BlockStack gap="050">
542→                    <InlineStack gap="200" blockAlign="center">
543→                      <Text as="h3" variant="headingSm" fontWeight="bold">
544→                        Free
545→                      </Text>
546→                      {currentTier === "free" && <Badge tone="success">Active</Badge>}
547→                    </InlineStack>
548→                    <Text as="p" variant="bodySm" tone="subdued">
549→                      20 zip codes &middot; Basic widget &middot; Unlimited searches
550→                    </Text>
551→                  </BlockStack>
552→                </InlineStack>
553→                <InlineStack gap="200" blockAlign="center">
554→                  <Text as="p" variant="headingSm" fontWeight="bold">
555→                    $0
556→                  </Text>
557→                  <Text as="p" variant="bodySm" tone="subdued">
558→                    forever
559→                  </Text>
560→                </InlineStack>
561→              </InlineStack>
562→            </Box>
563→
564→            {/* Paid plan cards — 3 columns */}
565→            <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
566→              {(
567→                Object.values(PLANS_DATA)
568→                  .filter((plan) => plan.id !== "free") as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]
569→              ).map((plan) => (
570→                <PlanCard
571→                  key={plan.id}
572→                  plan={plan}
573→                  isAnnual={isAnnual}
574→                  currentTier={currentTier}
575→                  onSubscribe={handleSubscribe}
576→                  onRequestCancel={() => setCancelModalOpen(true)}
577→                  loadingPlan={loadingPlan}
578→                />
579→              ))}
580→            </InlineGrid>
581→
582→            {/* Downgrade to Free option */}
583→            {currentTier !== "free" && (
584→              <Box paddingBlockStart="100">
585→                <InlineStack align="center">
586→                  <Button
587→                    variant="plain"
588→                    tone="critical"
589→                    onClick={() => setCancelModalOpen(true)}
590→                  >
591→                    Downgrade to Free plan
592→                  </Button>
593→                </InlineStack>
594→              </Box>
595→            )}
596→
597→            {/* Trial footnote */}
598→            {(currentTier === "free" || currentTier === "starter") && (
599→              <Text
600→                as="p"
601→                variant="bodySm"
602→                tone="subdued"
603→                alignment="center"
604→              >
605→                All paid plans include a 7-day free trial. No credit card
606→                charged until the trial ends.
607→              </Text>
608→            )}
609→
610→            {/* Full Feature Comparison */}
611→            <BlockStack gap="400">
612→              <Text as="h2" variant="headingLg" alignment="center">
613→                Full Feature Comparison
614→              </Text>
615→              <Box
616→                background="bg-surface"
617→                borderWidth="025"
618→                borderColor="border"
619→                borderRadius="300"
620→                padding="400"
621→              >
622→                <BlockStack gap="0">
623→                  {/* Header row */}
624→                  <Box paddingBlockEnd="300">
625→                    <InlineStack align="space-between">
626→                      <Box minWidth="180px">
627→                        <Text as="p" variant="bodySm" tone="subdued" fontWeight="semibold">
628→                          Feature
629→                        </Text>
630→                      </Box>
631→                      {PLAN_ORDER.map((id) => {
632→                        const plan = PLANS_DATA[id];
633→                        return (
634→                          <Box key={id} minWidth="90px">
635→                            <BlockStack gap="050" inlineAlign="center">
