649→                      })}
650→                    </InlineStack>
651→                  </Box>
652→
653→                  <Divider />
654→
655→                  {/* Feature rows */}
656→                  {FEATURE_ROWS.map((row, i) => (
657→                    <Box key={row.label} paddingBlock="200">
658→                      <InlineStack align="space-between" blockAlign="center">
659→                        <Box minWidth="180px">
660→                          <Text as="p" variant="bodyMd">
661→                            {row.label}
662→                          </Text>
663→                        </Box>
664→                        {PLAN_ORDER.map((id) => {
