666→                          return (
667→                            <Box key={id} minWidth="90px">
668→                              <InlineStack align="center">
669→                                {typeof val === "string" ? (
670→                                  <Text as="p" variant="bodyMd" fontWeight="semibold" alignment="center">
671→                                    {val}
672→                                  </Text>
673→                                ) : (
674→                                  <Icon
675→                                    source={val ? CheckCircleIcon : XCircleIcon}
676→                                    tone={val ? "success" : "subdued"}
677→                                  />
678→                                )}
679→                              </InlineStack>
680→                            </Box>
681→                          );
682→                        })}
683→                      </InlineStack>
684→                      {i < FEATURE_ROWS.length - 1 && <Box paddingBlockStart="200"><Divider /></Box>}
685→                    </Box>
686→                  ))}
687→                </BlockStack>
688→              </Box>
689→            </BlockStack>
690→
691→            {/* Set plan directly (for custom app testing) */}
692→            <Banner tone="info" title="Set Plan Manually">
693→              <BlockStack gap="300">
694→                <Text as="p" variant="bodySm">
695→                  Select a plan to activate it directly:
696→                </Text>
697→                <InlineStack gap="200">
698→                  {(["free", "starter", "pro", "ultimate"] as const).map((tier) => (
699→                    <Button
700→                      key={tier}
701→                      size="slim"
702→                      variant={currentTier === tier ? "primary" : "secondary"}
703→                      disabled={currentTier === tier}
704→                      onClick={() => {
