706→                        fd.set("intent", "test-set-plan");
707→                        fd.set("tier", tier);
708→                        fetcher.submit(fd, { method: "POST" });
709→                      }}
710→                    >
711→                      {tier.charAt(0).toUpperCase() + tier.slice(1)}
712→                    </Button>
713→                  ))}
714→                </InlineStack>
715→              </BlockStack>
716→            </Banner>
717→
718→          </BlockStack>
719→        </Layout.Section>
720→      </Layout>
721→      </Box>
722→
723→      {/* Downgrade confirmation modal */}
724→      <Modal
725→        open={cancelModalOpen}
726→        onClose={() => setCancelModalOpen(false)}
727→        title="Downgrade to Free plan?"
728→        primaryAction={{
729→          content: "Yes, downgrade",
730→          destructive: true,
731→          onAction: handleConfirmCancel,
732→          loading: loadingPlan === "cancel",
733→        }}
734→        secondaryActions={[
735→          {
736→            content: "Keep current plan",
737→            onAction: () => setCancelModalOpen(false),
738→          },
739→        ]}
740→      >
741→        <Modal.Section>
742→          <BlockStack gap="400">
743→            <Text as="p" variant="bodyMd">
744→              Downgrading to Free will immediately remove access to:
745→            </Text>
746→            <BlockStack gap="200">
747→              {[
748→                "Unlimited zip codes — limited to 20",
749→                "Blocked zip codes",
750→                "Delivery rules, zones & ETAs",
751→                "Bulk CSV import & export",
752→                "Customer waitlist",
753→                "Widget customization (colors, position)",
754→                "Cart & checkout blocking",
755→              ].map((item) => (
756→                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
757→                  <Text as="span" variant="bodyMd" tone="subdued">·</Text>
758→                  <Text as="p" variant="bodyMd">{item}</Text>
